#!/usr/bin/env bash
# Install an nftables table that isolates lab VMs:
#  - VMs may reach the internet,
#  - VMs may reach the host only on DNS/DHCP + the lab service ports (Gitea, registry, Ollama),
#  - VMs may NOT reach your LAN or any other private network.
# Uses its own table + systemd unit, so it never flushes libvirt/Docker rules. Idempotent.
source "$(dirname "$0")/../lib/common.sh"

PORTS="$GITEA_HTTP_PORT, $GITEA_SSH_PORT, $REGISTRY_PORT, $OLLAMA_PORT"
rules=$(mktemp)
cat >"$rules" <<EOF
#!/usr/sbin/nft -f
# Generated by agentlab/host/firewall.sh — edit config.env and re-run instead.
table inet agentlab
delete table inet agentlab

table inet agentlab {
  set blocked_v4 {
    type ipv4_addr
    flags interval
    elements = { $BLOCKED_NETS }
  }

  # Traffic from VMs to the host itself
  chain input {
    type filter hook input priority filter - 10; policy accept;
    iifname != "$LAB_BRIDGE" accept
    ct state established,related accept
    icmp type echo-request accept
    udp dport { 53, 67 } accept
    tcp dport 53 accept
    ip daddr $LAB_GW_IP tcp dport { $PORTS } accept
    counter drop
  }

  # Traffic from VMs routed through the host
  chain forward {
    type filter hook forward priority filter - 10; policy accept;
    iifname != "$LAB_BRIDGE" accept
    ct state established,related accept
    # Docker-published lab services on the gateway IP (DNAT to a container)
    ct status dnat ct original ip daddr $LAB_GW_IP ct original proto-dst { $PORTS } accept
    ip daddr @blocked_v4 counter drop
    meta nfproto ipv6 counter drop
  }
}
EOF

log "Installing /etc/agentlab/agentlab.nft and agentlab-firewall.service"
sudo install -D -m 0644 "$rules" /etc/agentlab/agentlab.nft
rm -f "$rules"
sudo tee /etc/systemd/system/agentlab-firewall.service >/dev/null <<'EOF'
[Unit]
Description=agentlab nftables rules (isolate lab VMs from LAN and host)
Wants=network-pre.target
Before=network-pre.target libvirtd.service docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/sbin/nft -f /etc/agentlab/agentlab.nft
ExecStop=/usr/sbin/nft delete table inet agentlab

[Install]
WantedBy=multi-user.target
EOF
sudo systemctl daemon-reload
sudo systemctl enable agentlab-firewall.service >/dev/null
sudo systemctl restart agentlab-firewall.service
log "Firewall active (inspect with: sudo nft list table inet agentlab)"
